var mcuIp = "20.0.0.2";
var port = 1234;
var socket;
var i=0;

function jsonParse(text, reviver) {
            var j;
            function walk(holder, key) {
                var k, v, value = holder[key];
                if (value && typeof value === 'object') {
                    for (k in value) {
                        if (Object.prototype.hasOwnProperty.call(value, k)) {
                            v = walk(value, k);
                            if (v !== undefined) {
                                value[k] = v;
                            } else {
                                delete value[k];
                            }
                        }
                    }
                }
                return reviver.call(holder, key, value);
            }

            j = eval('(' + text + ')');
            return typeof reviver === 'function' ? walk({'': j}, '') : j;
}

function loop()
{
	var pdu;
	if (i == 0)
	{
		Device.println("turn LED red");
		pdu = '{"data": "red"}';
	}
	else if (i == 1)
	{
		Device.println("turn LED green");
		pdu = '{"data": "green"}';
	}
	else
	{
		Device.println("turn LED blue");
		pdu = '{"data": "blue"}';
	}
	i = (i+1)%3;
	socket.send(mcuIp, port, pdu);
	delay(5000);
}


function main()
{
	socket = new UDPSocket();
	socket.begin(port);
}

